    "description": "Pelvic Tilt Into Bridge. Fiche banque « Fessiers » — équipement : Divers. Cible principale : Fessiers. Muscles secondaires : Ischio-jambiers, Quadriceps. Charnière de hanches, dos neutre, tibias relativement stables. La charge reste proche du corps. Pousse les hanches vers l’arrière, ressent l’arrière de cuisse / fessiers, reviens en extension de hanches sans cambrer excessivement. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille fessiers. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
