    "description": "Barre Squat Jump Step Rear Lunge. Fiche banque « Quadriceps » — équipement : Barre. Cible principale : Quadriceps. Muscles secondaires : Fessiers, Ischio-jambiers. Rythme régulier, respiration ouverte. Qualité du pattern avant la vitesse. Enchaîne les cycles en restant précis : chaque répétition ressemble à la précédente. Reste sur cette variante précise — ne la confonds pas avec un mouvement voisin de la même famille quadriceps. Respiration : expire sur la phase d’effort (poussée, tirage ou contraction), inspire sur le retour contrôlé. Repères de séance types : 3 à 4 séries de 8 à 15 répétitions (ou 6 à 10 si la charge est lourde / le geste exigeant), repos 60 à 90 s. Le GIF montre la trajectoire de référence : reproduis-la avant d’augmenter la charge.",
